import {deformableParticleCount,validDeformableMassWeights} from './deformable-distribution.js';
export function editClothMassWeight(rows,count,index,weight){
 if(!validDeformableMassWeights({particles:count,massWeights:rows})||!Number.isSafeInteger(index)||index<0||index>=count||!Number.isFinite(weight)||weight<.001||weight>1000)throw Error('입자 번호와 질량 가중치를 확인하세요.');
 const found=rows.find(r=>r.index===index);if(found?.weight===weight&&weight!==1||!found&&weight===1)return rows;const next=rows.filter(r=>r.index!==index);if(weight!==1)next.push({index,weight});return next;
}
export function clothMassControls(p,attrs,esc,{disabled=false}={}){
 const count=deformableParticleCount(p),rows=p.massWeights||[],off=disabled?' disabled':'';
 return '<div class="cloth-mass-editor" data-cloth-mass-count="'+count+'"><input type="hidden" '+attrs+' data-cloth-mass-change value="'+esc(JSON.stringify(rows))+'">'+
 '<div class="component-vector"><label>입자 번호<input type="number" data-cloth-mass-index min="0" max="'+(count-1)+'" step="1" value="0" aria-label="질량 입자 번호"'+off+'></label><label>가중치<input type="number" data-cloth-mass-weight min=".001" max="1000" step=".1" value="'+(rows.find(r=>r.index===0)?.weight??1)+'" aria-label="입자 질량 가중치"'+off+'></label></div><div class="cloth-pin-summary"><span>'+rows.length+' / '+count+' 지정</span><button type="button" data-cloth-mass-action="set"'+off+'>지정</button><button type="button" data-cloth-mass-action="remove"'+off+'>기본값</button><button type="button" data-cloth-mass-action="clear"'+off+'>전체 초기화</button></div></div>';
}
export function handleClothMassIndex(event){const input=event.target.closest?.('[data-cloth-mass-index]');if(!input||input.disabled)return false;const root=input.closest('.cloth-mass-editor'),index=Number(input.value),count=Number(root.dataset.clothMassCount);if(!Number.isSafeInteger(index)||index<0||index>=count)throw Error('입자 번호 범위를 확인하세요.');const rows=JSON.parse(root.querySelector('[data-cloth-mass-change]').value);root.querySelector('[data-cloth-mass-weight]').value=String(rows.find(r=>r.index===index)?.weight??1);return true;}
export function handleClothMassClick(event){
 const button=event.target.closest?.('[data-cloth-mass-action]');if(!button||button.disabled)return false;const root=button.closest('.cloth-mass-editor'),input=root.querySelector('[data-cloth-mass-change]'),count=Number(root.dataset.clothMassCount),index=Number(root.querySelector('[data-cloth-mass-index]').value),rows=JSON.parse(input.value),action=button.dataset.clothMassAction;
 if(!['set','remove','clear'].includes(action))throw Error('질량 편집 동작을 확인하세요.');const next=action==='clear'?[]:editClothMassWeight(rows,count,index,action==='remove'?1:Number(root.querySelector('[data-cloth-mass-weight]').value));event.preventDefault();event.stopPropagation();if(JSON.stringify(next)===JSON.stringify(rows))return true;input.value=JSON.stringify(next);const doc=input.ownerDocument;input.dispatchEvent(new doc.defaultView.Event('change',{bubbles:true}));
 const replacement=[...doc.querySelectorAll('[data-cloth-mass-change]')].find(el=>el.dataset.sceneComponent===input.dataset.sceneComponent&&el.dataset.componentProperty===input.dataset.componentProperty&&el.dataset.componentField===input.dataset.componentField);if(replacement){const view=replacement.closest('.cloth-mass-editor'),field=view.querySelector('[data-cloth-mass-index]');const restored=Number.isSafeInteger(index)&&index>=0&&index<count?index:0;field.value=String(restored);view.querySelector('[data-cloth-mass-weight]').value=String(next.find(r=>r.index===restored)?.weight??1);field.focus({preventScroll:true});}return true;
}
